import pandas as pd

files = [
    'experiment_10_csv', 'experiment_1_csv', 'experiment_2_csv',
    'experiment_3_csv', 'experiment_4_csv', 'experiment_5_csv',
    'experiment_7_csv', 'experiment_8_csv', 'experiment_9_csv'
]

dfs = []
for f in files:
    try:
        dfs.append(pd.read_csv(eval(f)))
    except:
        pass

if dfs:
    df = pd.concat(dfs, ignore_index=True)
    print(f"Rows: {len(df)}, Cols: {df.columns.tolist()}")
    print(df.corr(numeric_only=True)["JobThroughput"].dropna().sort_values(ascending=False).round(3))
else:
    print("No data loaded")
